def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find horizontal bars as contiguous nonzero runs, allowing one-cell gaps.
    bars = []
    for r, row in enumerate(grid):
        runs = []
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            color = row[c]
            end = c
            c += 1
            while c < w and (row[c] == color or (row[c] == 0 and c + 1 < w and row[c + 1] == color)):
                if row[c] == color:
                    end = c
                c += 1
            if end - start >= 2:
                runs.append((start, end, color))
                for x in range(start, end + 1):
                    if row[x] == 0:
                        out[r][x] = color
        if runs:
            bars.append((r, runs))

    # Each bottom vertical marker continues upward, taking the color of
    # the nearest horizontal bar run that reaches its column.
    for c in range(w):
        marker = grid[h - 1][c]
        if marker == 0:
            continue
        runs_at = []
        for r, runs in bars:
            for a, b, color in runs:
                if a <= c <= b:
                    runs_at.append((r, color))
                    break
        for r in range(h):
            above = [(br, color) for br, color in runs_at if br >= r]
            if above:
                br, color = min(above)
                out[r][c] = color
            else:
                out[r][c] = marker
    return out
